head.script:
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("background-color");
    if (rgb.indexOf("rgb") != -1) {
        return rgb == "rgb(252, 167, 60)";
    }
    return rgb == hexa;
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper("#grid1_cell_0_0", "key-combo", {
        combo: "TAB"
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper("#grid1_cell_0_0", "key-combo", {
        combo: "RIGHT_ARROW"
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper("#G_grid1__column8", "key-combo", {
        combo: "RIGHT_ARROW"
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플실행 후 gridView의 첫번째 컬럼에 마우스를 클릭하고 tab을 클릭하여 이동한다.
    //1. After running the sample, click mouse on the first column of gridView and click tab to move.
    //Verify step 1. The tab is moved normally.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_grid1__column8').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 방향키로 이동해본다.
    //2. Go to the direction key.
    //Verify step 2. The merge column is also moved normally.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'grid1_cell_0_3', '#fca73c')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setRef({
        ref: "vector",
        baseNode: "vector",
        repeatNode: "data"
    });
    window.mergeInfo = {
        rowIndex: "0",
        colIndex: "1",
        colSpan: "2",
        rowSpan: "1"
    };
    grid1.mergeCell(mergeInfo);
    window.mergeInfo = {
        rowIndex: "1",
        colIndex: "2",
        colSpan: "2",
        rowSpan: "1"
    };
    grid1.mergeCell(mergeInfo);
    window.mergeInfo = {
        rowIndex: "2",
        colIndex: "3",
        colSpan: "2",
        rowSpan: "1"
    };
    grid1.mergeCell(mergeInfo);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 20-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
